import {radarAreaState} from './map-radar-check.js';
const $=s=>document.querySelector(s),reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
export function radarFrames(data){const host=new URL(data.host);if(host.protocol!=='https:'||!/(^|\.)rainviewer\.com$/.test(host.hostname))throw Error('Fonte radar non valida');const past=(data.radar?.past||[]).filter(f=>Number.isFinite(f.time)&&/^\/v2\/radar\/[\w/-]+$/.test(f.path)).sort((a,b)=>a.time-b.time);const last=past.at(-1)?.time;return past.filter(f=>f.time>=last-3600&&f.time<=Date.now()/1000+60).map(f=>({...f,url:host.origin+f.path+'/256/{z}/{x}/{y}/2/1_1.png'}))}
export function windVector(speed,from){const r=from*Math.PI/180;return {u:-Math.sin(r)*speed,v:-Math.cos(r)*speed}}
export function interpolateTemperature(points,lat,lon){let total=0,sum=0;for(const p of points){if(!Number.isFinite(p.temperature_2m))continue;const d=(p.latitude-lat)**2+((p.longitude-lon)*Math.cos(lat*Math.PI/180))**2;if(d<1e-12)return p.temperature_2m;const w=1/d;sum+=p.temperature_2m*w;total+=w}return total?sum/total:null}
export function temperatureColor(t){const stops=[[-10,[53,105,238]],[10,[72,192,229]],[22,[247,215,82]],[40,[233,64,58]]];if(t<=-10)return stops[0][1];for(let i=1;i<stops.length;i++){if(t<=stops[i][0]){const a=stops[i-1],b=stops[i],f=(t-a[0])/(b[0]-a[0]);return a[1].map((v,j)=>Math.round(v+(b[1][j]-v)*f))}}return stops.at(-1)[1]}
const cache=new Map();
export function createMapWeather(map,ctx,status){
 const selected=new Set();let frames=[],radarIndex=0,playing=false,radarTimer=0,radarAt=0,radarBusy=false,dead=false,controller=new AbortController(),grid=[],gridKey='',weatherRun=0,frame=0,lastFrame=0,particles=[],resizeTimer=0,radarState='unknown',radarCheck=0,radarController=null,gridController=null,tapped=null;
 const canvas=document.createElement('canvas');canvas.className='local-weather-canvas';canvas.setAttribute('aria-hidden','true');map.getContainer().append(canvas);const c=canvas.getContext('2d');
 const note=text=>{const el=$('#local-map-weather-note');if(el)el.textContent=text};
 function select(kind){weatherRun++;gridController?.abort();radarCheck++;radarController?.abort();selected.clear();selected.add(kind);tapped=null;pause();radarState='unknown';document.querySelectorAll('[data-map-layer]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mapLayer===kind)));showRadar();legend();note('');status('');if(kind==='rain'){loadRadar();checkRain()}else loadGrid();paintStatic();visibility()}
 document.querySelectorAll('[data-map-layer]').forEach(b=>b.onclick=()=>select(b.dataset.mapLayer));
 const readout=document.createElement('output');readout.className='map-temperature-value';readout.hidden=true;map.getContainer().append(readout);
 function legend(){const el=$('#local-map-legend');if(!el)return;const wind=selected.has('wind'),temp=selected.has('temperature');el.hidden=!wind&&!temp;el.innerHTML=wind?'<b>Vento · km/h</b><span class="wind-scale"></span><div><span>0</span><span>20</span><span>40</span><span>60+</span></div>':temp?'<b>Temperatura · °C</b><span class="temperature-scale"></span><div><span>−10</span><span>10</span><span>22</span><span>40+</span></div>':''}
 async function checkRain(){const token=++radarCheck;radarController?.abort();radarController=new AbortController();radarState='unknown';showRadar();if(!selected.has('rain')||!frames.length)return;const result=await radarAreaState(frames,gridBounds(),map.getZoom(),AbortSignal.any([controller.signal,radarController.signal,AbortSignal.timeout(18000)]));if(dead||token!==radarCheck||!selected.has('rain'))return;radarState=result;if(result==='dry')pause();showRadar();note(result==='unknown'?'Copertura radar non verificata':'')}
 $('[data-radar-play]').onclick=()=>{if(playing)pause();else{if(radarState==='dry'||frames.length<2)return;playing=true;$('[data-radar-play]').textContent='Ⅱ';$('[data-radar-play]').setAttribute('aria-label','Pausa radar');advance()}};
 $('[data-radar-range]').oninput=e=>{pause();radarIndex=+e.target.value;showRadar()};
 function pause(){playing=false;clearTimeout(radarTimer);const b=$('[data-radar-play]');if(b){b.textContent='▶';b.setAttribute('aria-label','Riproduci radar')}}
 function showRadar(){if(dead)return;const dry=$('#local-rain-empty');if(dry)dry.hidden=!selected.has('rain')||radarState!=='dry';frames.forEach((f,i)=>{if(map.getLayer('radar-'+i))map.setPaintProperty('radar-'+i,'raster-opacity',selected.has('rain')&&i===radarIndex ? .68 : 0)});const controls=$('#local-radar-controls');if(controls)controls.hidden=!selected.has('rain')||!frames.length;const current=frames[radarIndex];if(current){$('[data-radar-range]').max=frames.length-1;$('[data-radar-range]').value=radarIndex;$('[data-radar-time]').textContent=new Date(current.time*1000).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'});$('[data-radar-play]').disabled=frames.length<2||radarState==='dry';}}
 function advance(){if(dead||!playing||document.hidden||!selected.has('rain'))return pause();radarIndex=(radarIndex+1)%frames.length;showRadar();radarTimer=setTimeout(advance,900)}
 async function loadRadar(){if(radarBusy)return;if(frames.length&&Date.now()-radarAt<300000){showRadar();return}radarBusy=true;status('Carico le immagini radar…');try{const response=await fetch('https://api.rainviewer.com/public/weather-maps.json',{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(15000)])});if(!response.ok)throw Error();const next=radarFrames(await response.json());if(dead)return;if(!next.length)throw Error();pause();frames.forEach((f,i)=>{if(map.getLayer('radar-'+i))map.removeLayer('radar-'+i);if(map.getSource('radar-'+i))map.removeSource('radar-'+i)});frames=next;frames.forEach((f,i)=>{map.addSource('radar-'+i,{type:'raster',tiles:[f.url],tileSize:256,maxzoom:7,attribution:'<a href="https://www.rainviewer.com/" target="_blank" rel="noopener">RainViewer</a>'});map.addLayer({id:'radar-'+i,type:'raster',source:'radar-'+i,paint:{'raster-opacity':0,'raster-fade-duration':0}},'people-query')});radarIndex=frames.length-1;radarAt=Date.now();showRadar();checkRain();const age=Math.round(Date.now()/60000-frames.at(-1).time/60);if(selected.has('rain'))status(age>25?`Radar di ${age} min fa`: '');}catch(e){if(!dead&&selected.has('rain')&&e.name!=='AbortError')status('Radar non disponibile. Riprova toccando Pioggia.')}finally{radarBusy=false}}
 function gridBounds(){const b=map.getBounds();return {west:b.getWest(),east:b.getEast(),south:b.getSouth(),north:b.getNorth()}}
 async function loadGrid(){weatherRun++;gridController?.abort();gridController=new AbortController();if(!selected.has('wind')&&!selected.has('temperature')){note('');grid=[];paintStatic();return}const bounds=gridBounds();if(bounds.east-bounds.west>15||bounds.north-bounds.south>15||bounds.south< -85||bounds.north>85){grid=[];note('Avvicina la mappa per vedere vento e temperatura.');paintStatic();return}const key=Object.values(bounds).map(v=>v.toFixed(2)).join(','),token=++weatherRun;gridKey=key;note('Carico il meteo della zona…');let value=cache.get(key);try{if(!value||Date.now()-value.at>600000){const points=[];for(let y=0;y<5;y++)for(let x=0;x<5;x++)points.push({latitude:bounds.south+(bounds.north-bounds.south)*y/4,longitude:bounds.west+(bounds.east-bounds.west)*x/4});const url='https://api.open-meteo.com/v1/forecast?'+new URLSearchParams({latitude:points.map(p=>p.latitude.toFixed(4)).join(','),longitude:points.map(p=>p.longitude.toFixed(4)).join(','),current:'temperature_2m,wind_speed_10m,wind_direction_10m',wind_speed_unit:'kmh',timeformat:'unixtime'});const response=await fetch(url,{signal:AbortSignal.any([controller.signal,gridController.signal,AbortSignal.timeout(15000)])});if(!response.ok)throw Error();const data=await response.json();if(!Array.isArray(data)||data.length!==points.length)throw Error();value={at:Date.now(),rows:points.map((p,i)=>({...p,...data[i].current})).filter(p=>Number.isFinite(p.time)&&Math.abs(Date.now()/1000-p.time)<10800)};if(!value.rows.length)throw Error();cache.set(key,value);if(cache.size>8)cache.delete(cache.keys().next().value)}if(dead||token!==weatherRun||key!==gridKey)return;grid=value.rows;const times=grid.map(p=>p.time);note('Open-Meteo · '+new Date(Math.min(...times)*1000).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'}));particles=[];paintStatic();visibility()}catch(e){if(!dead&&token===weatherRun){grid=[];paintStatic();note('Meteo della mappa non disponibile. Riprova cambiando livello.')}}}
 function size(){const box=map.getContainer().getBoundingClientRect();if(canvas.width!==Math.round(box.width)||canvas.height!==Math.round(box.height)){canvas.width=Math.round(box.width);canvas.height=Math.round(box.height);particles=[]}}
 function temperatures(){const {place,weather}=ctx.get(),t=weather?.current?.temperature_2m;return Number.isFinite(t)?[...grid.filter(p=>Math.abs(p.latitude-place.latitude)+Math.abs(p.longitude-place.longitude)>1e-7),{...place,temperature_2m:t}]:grid}
 function temperature(){readout.hidden=!selected.has('temperature')||!grid.length;if(readout.hidden)return;const points=temperatures(),small=document.createElement('canvas');small.width=Math.max(2,Math.ceil(canvas.width/10));small.height=Math.max(2,Math.ceil(canvas.height/10));const sc=small.getContext('2d'),data=sc.createImageData(small.width,small.height);for(let y=0;y<small.height;y++)for(let x=0;x<small.width;x++){const ll=map.unproject([x/(small.width-1)*canvas.width,y/(small.height-1)*canvas.height]),t=interpolateTemperature(points,ll.lat,ll.lng);if(t===null)continue;const rgb=temperatureColor(t),i=(y*small.width+x)*4;data.data.set([...rgb,128],i)}sc.putImageData(data,0,0);c.imageSmoothingEnabled=true;c.drawImage(small,0,0,canvas.width,canvas.height);const ll=tapped||map.getCenter(),t=interpolateTemperature(points,ll.lat,ll.lng),q=tapped?map.project(tapped):{x:canvas.width/2,y:canvas.height/2};readout.textContent=t===null?'—':Math.round(t)+'°';readout.style.left=q.x+'px';readout.style.top=q.y+'px'}
 function pickTemperature(e){if(selected.has('temperature')){tapped=e.lngLat;paintStatic()}}
 map.on('click',pickTemperature);
 function paintStatic(){if(dead)return;size();c.clearRect(0,0,canvas.width,canvas.height);readout.hidden=!selected.has('temperature');temperature();if(selected.has('wind')&&(reduced()||document.documentElement.classList.contains('eco-mode'))){for(const p of grid){if(!Number.isFinite(p.wind_speed_10m)||!Number.isFinite(p.wind_direction_10m))continue;const q=map.project([p.longitude,p.latitude]),v=windVector(p.wind_speed_10m,p.wind_direction_10m);c.strokeStyle='#b7e8ff';c.lineWidth=2;c.beginPath();c.moveTo(q.x,q.y);c.lineTo(q.x+v.u*.5,q.y-v.v*.5);c.stroke();c.fillStyle='#fff';c.font='14px system-ui';c.fillText(Math.round(p.wind_speed_10m)+' km/h',q.x,q.y+20)}}}
 function vector(x,y){const ll=map.unproject([x,y]);let u=0,v=0,total=0;for(const p of grid){if(!Number.isFinite(p.wind_speed_10m)||!Number.isFinite(p.wind_direction_10m))continue;const weight=1/Math.max(.000001,(p.latitude-ll.lat)**2+((p.longitude-ll.lng)*Math.cos(ll.lat*Math.PI/180))**2),w=windVector(p.wind_speed_10m,p.wind_direction_10m);u+=w.u*weight;v+=w.v*weight;total+=weight}return total?{u:u/total,v:v/total}:null}
 function animate(t){frame=0;if(dead||document.hidden||reduced()||!selected.has('wind')||!grid.length)return;const dt=Math.min(50,t-lastFrame||16)/1000;lastFrame=t;size();c.globalCompositeOperation='destination-in';c.fillStyle='rgba(0,0,0,.92)';c.fillRect(0,0,canvas.width,canvas.height);c.globalCompositeOperation='source-over';while(particles.length<140)particles.push({x:Math.random()*canvas.width,y:Math.random()*canvas.height,age:Math.random()*2});c.strokeStyle='#b7e8ff';c.lineWidth=2.2;c.lineCap='round';for(const p of particles){const v=vector(p.x,p.y);if(!v)continue;const x=p.x+v.u*dt*2.5,y=p.y-v.v*dt*2.5;const speed=Math.hypot(v.u,v.v);c.strokeStyle=speed<20?'#a7e2ff':speed<40?'#ffe08b':'#ff927c';c.beginPath();c.moveTo(p.x-v.u*.22,p.y+v.v*.22);c.lineTo(x,y);c.stroke();p.x=x;p.y=y;p.age+=dt;if(p.age>3||x<0||y<0||x>canvas.width||y>canvas.height){p.x=Math.random()*canvas.width;p.y=Math.random()*canvas.height;p.age=0}}frame=requestAnimationFrame(animate)}
 function visibility(){cancelAnimationFrame(frame);frame=0;lastFrame=0;if(document.hidden){pause();return}paintStatic();if(selected.has('wind')&&!reduced()&&!document.documentElement.classList.contains('eco-mode')&&grid.length)frame=requestAnimationFrame(animate)}
 function viewChanged(){clearTimeout(resizeTimer);tapped=null;paintStatic();resizeTimer=setTimeout(()=>{if(!dead){loadGrid();checkRain()}},400)}
 map.on('movestart',()=>{radarCheck++;radarController?.abort();radarState='unknown';pause();showRadar()});map.on('move',()=>{tapped=null;paintStatic()});map.on('resize',viewChanged);const timer=setInterval(()=>{if(!document.hidden){if(selected.has('rain'))loadRadar();if(selected.has('wind')||selected.has('temperature'))loadGrid()}},300000);const media=matchMedia('(prefers-reduced-motion: reduce)');media.addEventListener('change',visibility);
 select('rain');
 return {viewChanged,visibility,refreshCity:paintStatic,radarError(){radarCheck++;radarController?.abort();radarState='unknown';showRadar();pause();if(selected.has('rain'))status('Alcune immagini radar non sono disponibili.');},dispose(){dead=true;controller.abort();radarController?.abort();gridController?.abort();readout.remove();cancelAnimationFrame(frame);clearTimeout(resizeTimer);clearInterval(timer);pause();media.removeEventListener('change',visibility);canvas.remove()}};
}
